INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ceeb878f-4f25-5ca3-be07-a031fdad82ad', 'b0000000-0000-0000-0000-000000000012', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', $$Which Junos protocol preference value is used for OSPF internal routes by default?$$::text, $$[{"id": "A", "text": "10", "is_correct": false}, {"id": "B", "text": "150", "is_correct": false}, {"id": "C", "text": "10", "is_correct": false}, {"id": "D", "text": "110", "is_correct": true}]$$::jsonb, $$Junos default protocol preference for OSPF internal routes is 110.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncis-ent.html"}$$::text[], $$OSPF$$::text, 20.0, '02fa46e6d380c1b5', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('06cd573e-916e-5d5a-82c2-df7457d26337', 'b0000000-0000-0000-0000-000000000012', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', $$What is the default OSPF reference-bandwidth on Junos?$$::text, $$[{"id": "A", "text": "100 Mbps", "is_correct": true}, {"id": "B", "text": "1 Gbps", "is_correct": false}, {"id": "C", "text": "10 Gbps", "is_correct": false}, {"id": "D", "text": "100 Gbps", "is_correct": false}]$$::jsonb, $$The default OSPF reference-bandwidth in Junos is 100 Mbps, which can cause incorrect cost on high-speed links.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncis-ent.html"}$$::text[], $$OSPF$$::text, 20.0, 'addf3bf60647f12a', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2380fcbe-fd23-50b9-a483-06b59add41f0', 'b0000000-0000-0000-0000-000000000012', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', $$Which BGP well-known discretionary attribute is used to influence outbound traffic?$$::text, $$[{"id": "A", "text": "MED", "is_correct": false}, {"id": "B", "text": "Local Preference", "is_correct": true}, {"id": "C", "text": "Origin", "is_correct": false}, {"id": "D", "text": "AS Path", "is_correct": false}]$$::jsonb, $$Local Preference is a well-known discretionary attribute that influences outbound traffic from an AS.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncis-ent.html"}$$::text[], $$BGP$$::text, 20.0, 'd6abd15379e38f10', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('98c5d403-3747-547d-9f17-96771aeedc4f', 'b0000000-0000-0000-0000-000000000012', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', $$In Junos, which command displays the BGP routes received from a specific neighbor?$$::text, $$[{"id": "A", "text": "show route receive-protocol bgp <neighbor>", "is_correct": true}, {"id": "B", "text": "show bgp neighbor <neighbor> routes", "is_correct": false}, {"id": "C", "text": "show route protocol bgp", "is_correct": false}, {"id": "D", "text": "show bgp summary", "is_correct": false}]$$::jsonb, $$'show route receive-protocol bgp <neighbor>' displays routes received from a specific BGP peer.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncis-ent.html"}$$::text[], $$BGP$$::text, 20.0, '78ccf79771b32786', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6ab59b24-5638-5180-a3d8-a0f4bb8541dd', 'b0000000-0000-0000-0000-000000000012', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', $$Which spanning-tree protocol is the IEEE standard that allows multiple spanning trees per VLAN?$$::text, $$[{"id": "A", "text": "RSTP", "is_correct": false}, {"id": "B", "text": "MSTP", "is_correct": true}, {"id": "C", "text": "VSTP", "is_correct": false}, {"id": "D", "text": "STP", "is_correct": false}]$$::jsonb, $$MSTP (802.1s) maps VLANs to multiple spanning-tree instances. VSTP is Juniper per-VLAN.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncis-ent.html"}$$::text[], $$Layer 2$$::text, 15.0, '3bfcfc8e49fa4867', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('82e1dc55-bfce-5a4b-9719-fa85b3824baa', 'b0000000-0000-0000-0000-000000000012', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', $$In an EVPN-VXLAN campus fabric, which device typically acts as the VTEP?$$::text, $$[{"id": "A", "text": "Core router", "is_correct": false}, {"id": "B", "text": "Access switch or satellite device", "is_correct": true}, {"id": "C", "text": "DHCP server", "is_correct": false}, {"id": "D", "text": "Firewall", "is_correct": false}]$$::jsonb, $$In EVPN-VXLAN fabrics, access switches or satellite devices commonly act as VTEPs.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncis-ent.html"}$$::text[], $$EVPN/VXLAN$$::text, 15.0, 'b40e48a34ed8b808', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('effa50f1-c95d-54e3-94ed-9da967030964', 'b0000000-0000-0000-0000-000000000012', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', $$Which CoS scheduling method services queues in a strict priority order before others?$$::text, $$[{"id": "A", "text": "Weighted round-robin", "is_correct": false}, {"id": "B", "text": "Strict-high priority", "is_correct": true}, {"id": "C", "text": "Random early detection", "is_correct": false}, {"id": "D", "text": "Tail drop", "is_correct": false}]$$::jsonb, $$Strict-high priority queues are serviced before other queues, useful for voice/video.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncis-ent.html"}$$::text[], $$CoS$$::text, 10.0, '87f3c160a989c644', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('94cc77a2-5d46-5b61-a688-40b38ceb3d4d', 'b0000000-0000-0000-0000-000000000012', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', $$Which Junos command verifies which interfaces are participating in a LAG?$$::text, $$[{"id": "A", "text": "show lacp interfaces", "is_correct": true}, {"id": "B", "text": "show interfaces ae0 extensive", "is_correct": false}, {"id": "C", "text": "show ethernet-switching interfaces", "is_correct": false}, {"id": "D", "text": "show chassis cluster interfaces", "is_correct": false}]$$::jsonb, $$'show lacp interfaces' displays LACP member interfaces and their states.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncis-ent.html"}$$::text[], $$Layer 2$$::text, 15.0, 'dd4700dfe2ebd795', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('df83e102-eb77-5a6a-ab77-7fca4796e304', 'b0000000-0000-0000-0000-000000000014', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', $$Which protocol distributes MPLS labels without traffic engineering extensions?$$::text, $$[{"id": "A", "text": "RSVP", "is_correct": false}, {"id": "B", "text": "LDP", "is_correct": true}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]$$::jsonb, $$LDP is used for label distribution in MPLS networks without TE.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncis-sp.html"}$$::text[], $$MPLS$$::text, 25.0, '06f77b17f5c14bc6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9a2ce216-5038-5304-932b-6bc272e87101', 'b0000000-0000-0000-0000-000000000014', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', $$What is the purpose of Penultimate Hop Popping (PHP) in MPLS?$$::text, $$[{"id": "A", "text": "To add an additional label at the egress", "is_correct": false}, {"id": "B", "text": "To remove the outer label before the egress PE", "is_correct": true}, {"id": "C", "text": "To encrypt MPLS packets", "is_correct": false}, {"id": "D", "text": "To signal TE tunnels", "is_correct": false}]$$::jsonb, $$PHP removes the MPLS label at the penultimate hop, reducing egress PE label lookup burden.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncis-sp.html"}$$::text[], $$MPLS$$::text, 25.0, 'c50a0ed4b7a5fbce', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('10de1395-bcea-5d86-9a80-8527df95e982', 'b0000000-0000-0000-0000-000000000014', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', $$Which RSVP object is used to reserve bandwidth along an LSP path?$$::text, $$[{"id": "A", "text": "Sender TSpec", "is_correct": true}, {"id": "B", "text": "Record Route", "is_correct": false}, {"id": "C", "text": "Session", "is_correct": false}, {"id": "D", "text": "Hello", "is_correct": false}]$$::jsonb, $$The Sender TSpec object in RSVP Path messages describes traffic characteristics and bandwidth requirements.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncis-sp.html"}$$::text[], $$MPLS Traffic Engineering$$::text, 20.0, '2c8305ba4b0025a1', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('542c0c73-79a4-5401-915d-5ad75bd78757', 'b0000000-0000-0000-0000-000000000014', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'remember', $$Which IS-IS TLV carries Segment Routing Global Block (SRGB) information?$$::text, $$[{"id": "A", "text": "IS reachability", "is_correct": false}, {"id": "B", "text": "Extended IP reachability", "is_correct": false}, {"id": "C", "text": "SR-Capability sub-TLV", "is_correct": true}, {"id": "D", "text": "Hostname", "is_correct": false}]$$::jsonb, $$SR-Capability sub-TLV advertises SRGB and algorithms for Segment Routing.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncis-sp.html"}$$::text[], $$IS-IS / Segment Routing$$::text, 15.0, '4d57570ada308531', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('80c31e83-4cc2-54b3-aceb-32f33be13edc', 'b0000000-0000-0000-0000-000000000014', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', $$In BGP, which attribute is prepended to influence inbound traffic from peers?$$::text, $$[{"id": "A", "text": "Local Preference", "is_correct": false}, {"id": "B", "text": "MED", "is_correct": false}, {"id": "C", "text": "AS Path", "is_correct": true}, {"id": "D", "text": "Community", "is_correct": false}]$$::jsonb, $$AS Path prepending makes routes less preferred for inbound traffic by making the AS path longer.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncis-sp.html"}$$::text[], $$BGP$$::text, 20.0, 'e31cd973cf640522', true) ON CONFLICT (id) DO NOTHING;
