INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9570f860-4a18-5461-9c93-c7e14ae10eb4', 'b0000000-0000-0000-0000-000000000025', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 3, 'understand', $$Which Junos security policy action permits traffic and logs session close?$$::text, $$[{"id": "A", "text": "permit", "is_correct": false}, {"id": "B", "text": "deny", "is_correct": false}, {"id": "C", "text": "permit log", "is_correct": false}, {"id": "D", "text": "permit count", "is_correct": true}]$$::jsonb, $$'permit count' permits traffic and counts/log session information. Logging options include session-init and session-close separately.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncis-sec.html"}$$::text[], $$Security Policies$$::text, 20.0, 'bc57d5928cfbbdde', true) ON CONFLICT (id) DO NOTHING;
