INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bed1b2a4-cb10-55fd-8fc0-97612cf9cd3e', 'b0000000-0000-0000-0000-000000000025', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'understand', $$Which IPS action drops the current packet and all subsequent packets in the session?$$::text, $$[{"id": "A", "text": "Drop packet", "is_correct": false}, {"id": "B", "text": "Drop connection", "is_correct": true}, {"id": "C", "text": "Ignore", "is_correct": false}, {"id": "D", "text": "Mark DSCP", "is_correct": false}]$$::jsonb, $$Drop connection blocks the entire session, not just the offending packet.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncis-sec.html"}$$::text[], $$IPS$$::text, 15.0, '7c1b77d5956e1d9d', true) ON CONFLICT (id) DO NOTHING;
