INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('22a544dd-eb8e-5c41-a238-8e4f6d6f6f7b', 'b0000000-0000-0000-0000-000000000025', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 3, 'understand', $$Which SSL proxy feature decrypts outbound HTTPS traffic for inspection?$$::text, $$[{"id": "A", "text": "SSL VPN", "is_correct": false}, {"id": "B", "text": "SSL Forward Proxy", "is_correct": true}, {"id": "C", "text": "Destination NAT", "is_correct": false}, {"id": "D", "text": "AppQoS", "is_correct": false}]$$::jsonb, $$SSL Forward Proxy decrypts outbound SSL/TLS traffic for UTM/IPS inspection.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncis-sec.html"}$$::text[], $$SSL Proxy$$::text, 15.0, '03a1ef231ad52904', true) ON CONFLICT (id) DO NOTHING;
