INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('17661f50-d857-51b3-8186-ab7b9f73db4e', 'b0000000-0000-0000-0000-000000000027', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'understand', $$Which EVPN route type is used for broadcast, unknown unicast, and multicast (BUM) traffic?$$::text, $$[{"id": "A", "text": "Type 1", "is_correct": true}, {"id": "B", "text": "Type 2", "is_correct": false}, {"id": "C", "text": "Type 3", "is_correct": false}, {"id": "D", "text": "Type 5", "is_correct": false}]$$::jsonb, $$EVPN Type 1 routes carry Ethernet auto-discovery (A-D) per ES and per EVI, used for BUM split-horizon.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncis-dc.html"}$$::text[], $$EVPN$$::text, 20.0, 'b4d91a789aea122b', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7cbde6f5-f190-508a-8148-ce8d19641e80', 'b0000000-0000-0000-0000-000000000027', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 2, 'understand', $$In a VXLAN-EVPN fabric, what does the VNI identify?$$::text, $$[{"id": "A", "text": "A tenant VRF", "is_correct": false}, {"id": "B", "text": "A Layer 2 segment or Layer 3 VRF", "is_correct": true}, {"id": "C", "text": "A BGP neighbor", "is_correct": false}, {"id": "D", "text": "A physical link", "is_correct": false}]$$::jsonb, $$VXLAN Network Identifier (VNI) identifies a Layer 2 segment (VLAN) or Layer 3 VRF in EVPN-VXLAN.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncis-dc.html"}$$::text[], $$VXLAN$$::text, 20.0, '3b309c7686b51141', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('507faa91-e054-57db-be8c-a08d22924a44', 'b0000000-0000-0000-0000-000000000027', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'understand', $$Which Junos feature provides active-active multihoming at the Layer 2 edge in EVPN?$$::text, $$[{"id": "A", "text": "MC-LAG", "is_correct": false}, {"id": "B", "text": "EVPN multihoming (EVI-ES)", "is_correct": true}, {"id": "C", "text": "VRRP", "is_correct": false}, {"id": "D", "text": "LACP", "is_correct": false}]$$::jsonb, $$EVPN multihoming (All-Active) provides active-active L2 multihoming via Ethernet Segments.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncis-dc.html"}$$::text[], $$EVPN$$::text, 20.0, '5291324bed86d800', true) ON CONFLICT (id) DO NOTHING;
