INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('13da2a16-fac6-58e0-aa3e-adca80c25bf7', 'b0000000-0000-0000-0000-000000000027', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 2, 'remember', $$Which QFabric component acts as the central routing and switching backplane?$$::text, $$[{"id": "A", "text": "Node device", "is_correct": false}, {"id": "B", "text": "Interconnect device", "is_correct": true}, {"id": "C", "text": "Director group", "is_correct": false}, {"id": "D", "text": "Fabric manager", "is_correct": false}]$$::jsonb, $$Interconnect devices in QFabric provide the central backplane fabric.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncis-dc.html"}$$::text[], $$QFabric$$::text, 10.0, '734cd7a8b5af3be5', true) ON CONFLICT (id) DO NOTHING;
